import heapq

def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)
    C = capacity + 1
    K = max_swaps + 1
    adj = [[] for _ in range(n)]
    for (u, v, m, e) in roads:
        adj[u].append((v, m, e))
    is_station = [False] * n
    for x in stations:
        is_station[x] = True

    INF = float('inf')
    # index = (node * C + charge) * K + k
    dist = [INF] * (n * C * K)

    start = (s * C + capacity) * K + 0
    dist[start] = 0
    heap = [(0, 0, s, capacity)]
    while heap:
        d, k, u, c = heapq.heappop(heap)
        idx = (u * C + c) * K + k
        if d > dist[idx]:
            continue
        if u == t:
            # popped in lexicographic (minutes, swaps) order -> optimal
            return (d, k)
        # drive roads
        for (v, m, e) in adj[u]:
            if e > 0 and c < e:
                continue
            nc = c - e
            if nc > capacity:
                nc = capacity
            nd = d + m
            nidx = (v * C + nc) * K + k
            if nd < dist[nidx]:
                dist[nidx] = nd
                heapq.heappush(heap, (nd, k, v, nc))
        # swap
        if is_station[u] and k < max_swaps:
            nd = d + swap_time
            nidx = (u * C + capacity) * K + (k + 1)
            if nd < dist[nidx]:
                dist[nidx] = nd
                heapq.heappush(heap, (nd, k + 1, u, capacity))
    return None

def best_context(messages, budget, max_gap, bonus):
    if budget < 0 or max_gap < 0:
        raise ValueError("budget and max_gap must be non-negative")

    n = len(messages)
    NEG = float('-inf')
    W = budget + 1

    pinned = [bool(m[2]) for m in messages]
    # prefix_pinned[k] = number of pinned among indices < k
    prefix_pinned = [0] * (n + 1)
    for k in range(n):
        prefix_pinned[k + 1] = prefix_pinned[k] + (1 if pinned[k] else 0)
    total_pinned = prefix_pinned[n]

    result = NEG
    # Empty set
    if n <= max_gap and total_pinned == 0:
        result = 0

    dp = [None] * n
    for i in range(n):
        L, v, _ = messages[i]
        L = int(L)
        best = [NEG] * W

        # i as the first kept message
        if i <= max_gap and prefix_pinned[i] == 0:
            best[0] = 0

        # i preceded by kept message j
        lo = max(0, i - max_gap - 1)
        j = i - 1
        while j >= lo:
            dj = dp[j]
            if dj is not None:
                if j == i - 1 and bonus != 0:
                    best = list(map(max, best, [x + bonus for x in dj]))
                else:
                    best = list(map(max, best, dj))
            if pinned[j]:
                break  # cannot skip over a pinned message
            j -= 1

        row = [NEG] * W
        any_valid = False
        if L <= budget:
            for w in range(W - L):
                b = best[w]
                if b != NEG:
                    row[w + L] = b + v
                    any_valid = True
        dp[i] = row if any_valid else None

        # i as the last kept message
        if any_valid and n - 1 - i <= max_gap and prefix_pinned[n] - prefix_pinned[i + 1] == 0:
            m = max(row)
            if m > result:
                result = m

    if result == NEG:
        return None
    return int(result)

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    n = len(parent)
    INF = float('inf')
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # BFS order from root; process in reverse for post-order.
    order = [0]
    for v in order:
        order.extend(children[v])

    sub_dem = [0] * n
    has_crit = [False] * n
    dp = [None] * n

    for v in reversed(order):
        sub_dem[v] = demand[v]
        has_crit[v] = bool(critical[v])
        cur = [INF] * (demand[v] + 1)
        cur[demand[v]] = 0
        for c in children[v]:
            sub_dem[v] += sub_dem[c]
            has_crit[v] = has_crit[v] or has_crit[c]
            dc = dp[c]
            # Keep option: loads limited by line capacity
            lim = min(len(dc), cap[c] + 1)
            f = dc[:lim]
            if not has_crit[c]:
                cut = cut_cost[c] + penalty * sub_dem[c]
                if not f:
                    f = [cut]
                elif cut < f[0]:
                    f[0] = cut
            # Trim trailing INF
            while f and f[-1] == INF:
                f.pop()
            if not f:
                return None  # child can be neither kept nor cut
            # Min-plus merge
            new = [INF] * (len(cur) + len(f) - 1)
            fl = [(j, fj) for j, fj in enumerate(f) if fj != INF]
            for i, ci in enumerate(cur):
                if ci == INF:
                    continue
                for j, fj in fl:
                    s = ci + fj
                    if s < new[i + j]:
                        new[i + j] = s
            while len(new) > 1 and new[-1] == INF:
                new.pop()
            cur = new
            dp[c] = None  # free memory
        dp[v] = cur

    root = dp[0]
    best = INF
    for L in range(min(len(root), root_cap + 1)):
        if root[L] < best:
            best = root[L]
    return None if best == INF else int(best)

import heapq

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0:
        return None

    INF = float('inf')
    n_st = len(transfer)
    best_b = [INF] * n_st          # min boardings among labels ready at station
    trip_b = {}                    # trip_id -> min boardings while seated

    conns = sorted(connections, key=lambda c: c[3])

    # pending labels: (ready_time, station, boardings)
    heap = [(start_time, source, 0)]
    answer = INF

    for trip, frm, to, dep, arr in conns:
        # Labels ready by `dep` become usable.
        while heap and heap[0][0] <= dep:
            _, st, b = heapq.heappop(heap)
            if b < best_b[st]:
                best_b[st] = b

        tb = trip_b.get(trip, INF)

        # Board here if it lowers the boarding count and stays within the limit.
        sb = best_b[frm]
        if sb != INF:
            cand = sb + 1
            if cand <= max_boardings and cand < tb:
                tb = cand
                trip_b[trip] = cand

        if tb == INF:
            continue

        # Optionally alight at `to`.
        if to == target:
            if arr < answer:
                answer = arr
        else:
            # Only useful if it can improve the station's boarding count.
            if tb < best_b[to] and tb < max_boardings:
                heapq.heappush(heap, (arr + transfer[to], to, tb))

    return None if answer == INF else answer

def run_lock_manager(ops):
    log = []
    state = {}            # tx -> 'A' active, 'W' waiting, 'F' finished
    waitinfo = {}         # tx -> (res, mode)
    holders = {}          # res -> {tx: mode}
    held = {}             # tx -> set(res)
    head = {}
    tail = {}
    uptail = {}           # res -> last queued upgrade tx (upgrades contiguous at front)
    prv = {}
    nxt = {}
    is_up = {}            # tx -> whether its queued request is an upgrade

    def q_remove(R, t):
        p = prv.pop(t, None)
        n = nxt.pop(t, None)
        if p is not None:
            nxt[p] = n
        else:
            head[R] = n
        if n is not None:
            prv[n] = p
        else:
            tail[R] = p
        if uptail.get(R) == t:
            uptail[R] = p  # predecessor of last upgrade is an upgrade or None

    def q_append(R, t):
        tl = tail.get(R)
        prv[t] = tl
        nxt[t] = None
        if tl is None:
            head[R] = t
        else:
            nxt[tl] = t
        tail[R] = t

    def q_insert_upgrade(R, t):
        u = uptail.get(R)
        if u is None:
            h = head.get(R)
            prv[t] = None
            nxt[t] = h
            head[R] = t
            if h is None:
                tail[R] = t
            else:
                prv[h] = t
        else:
            n = nxt[u]
            prv[t] = u
            nxt[t] = n
            nxt[u] = t
            if n is None:
                tail[R] = t
            else:
                prv[n] = t
        uptail[R] = t

    def process(R, i):
        h = holders.setdefault(R, {})
        while True:
            U = head.get(R)
            if U is None:
                return
            mode = waitinfo[U][1]
            ok = True
            if mode == "S":
                for v, m in h.items():
                    if v != U and m == "X":
                        ok = False
                        break
            else:
                for v in h:
                    if v != U:
                        ok = False
                        break
            if not ok:
                return
            q_remove(R, U)
            del waitinfo[U]
            is_up.pop(U, None)
            h[U] = mode
            held.setdefault(U, set()).add(R)
            state[U] = 'A'
            log.append(("GRANT", i, U, R, mode))

    def release(T, i):
        affected = set()
        if state.get(T) == 'W':
            R = waitinfo[T][0]
            q_remove(R, T)
            del waitinfo[T]
            is_up.pop(T, None)
            affected.add(R)
        hs = held.pop(T, None)
        if hs:
            for R in hs:
                del holders[R][T]
                affected.add(R)
        state[T] = 'F'
        for R in sorted(affected):
            process(R, i)

    def forward(T):
        F = set()
        flagged = set()
        stack = []
        R, M = waitinfo[T]
        p = prv.get(T)
        if p is not None:
            F.add(p); stack.append(p)
        h = holders.get(R, {})
        if M == "X":
            for v in h:
                if v != T and v not in F:
                    F.add(v); stack.append(v)
        else:
            if len(h) == 1:
                for v, m in h.items():
                    if m == "X" and v != T and v not in F:
                        F.add(v); stack.append(v)
        while stack:
            W = stack.pop()
            if state.get(W) != 'W':
                continue
            R, M = waitinfo[W]
            p = prv.get(W)
            if p is not None and p not in F:
                F.add(p); stack.append(p)
            h = holders.get(R, {})
            if M == "X":
                if R not in flagged:
                    flagged.add(R)
                    for v in h:
                        if v not in F:
                            F.add(v); stack.append(v)
            else:
                if len(h) == 1:
                    for v, m in h.items():
                        if m == "X" and v not in F:
                            F.add(v); stack.append(v)
        return F

    def backward(T, F):
        B = {T}
        stack = [T]
        while stack:
            V = stack.pop()
            if state.get(V) == 'W':
                n = nxt.get(V)
                if n is not None and n in F and n not in B:
                    B.add(n); stack.append(n)
            hs = held.get(V)
            if hs:
                for R in hs:
                    f = head.get(R)
                    if f is not None and f != V and f in F and f not in B:
                        B.add(f); stack.append(f)
        return B

    for i, op in enumerate(ops):
        kind = op[0]
        T = op[1]
        st = state.get(T)
        if st == 'W' or st == 'F':
            log.append(("IGNORED", i, T))
            continue
        if st is None:
            state[T] = 'A'
        if kind == "COMMIT":
            log.append(("COMMIT", i, T))
            release(T, i)
            continue
        R = op[2]
        M = kind
        h = holders.setdefault(R, {})
        cur = h.get(T)
        waited = False
        if cur == "X" or (cur == "S" and M == "S"):
            log.append(("HELD", i, T, R))
        elif cur == "S":  # upgrade
            if len(h) == 1:
                h[T] = "X"
                log.append(("GRANT", i, T, R, "X"))
            else:
                q_insert_upgrade(R, T)
                waitinfo[T] = (R, "X")
                is_up[T] = True
                state[T] = 'W'
                log.append(("WAIT", i, T, R, "X"))
                waited = True
        else:
            ok = head.get(R) is None
            if ok:
                if M == "X":
                    ok = not h
                else:
                    for m in h.values():
                        if m == "X":
                            ok = False
                            break
            if ok:
                h[T] = M
                held.setdefault(T, set()).add(R)
                log.append(("GRANT", i, T, R, M))
            else:
                q_append(R, T)
                waitinfo[T] = (R, M)
                state[T] = 'W'
                log.append(("WAIT", i, T, R, M))
                waited = True
        if waited:
            while state.get(T) == 'W':
                F = forward(T)
                if T not in F:
                    break
                B = backward(T, F)
                victim = max(B)
                log.append(("ABORT", i, victim))
                release(victim, i)
    return log

import re

_NAME = re.compile(r'[a-z0-9_]+')
_WORD = re.compile(r'[a-z]+')
_PRINCIPAL = re.compile(r'\*|(?:user|group):[a-z0-9_]+')
_ACTION = re.compile(r'\*|[a-z]+(?:,[a-z]+)*')
_RESOURCE = re.compile(r'/|(?:/(?:\*\*|\*|[a-z0-9._-]+))+')
_PATH = re.compile(r'/|(?:/[a-z0-9._-]+)+')


def _is_name(x):
    return isinstance(x, str) and _NAME.fullmatch(x) is not None


def _segments(p):
    return [] if p == "/" else p[1:].split("/")


class _Pattern:
    """Bitmask NFA over pattern positions 0..m (bit m = accept)."""
    __slots__ = ("m", "star1", "star2", "lits", "has_dstar", "nlit", "accept")

    def __init__(self, segs):
        self.m = len(segs)
        self.star1 = 0
        self.star2 = 0
        self.lits = {}
        for i, s in enumerate(segs):
            if s == "**":
                self.star2 |= 1 << i
            elif s == "*":
                self.star1 |= 1 << i
            else:
                self.lits[s] = self.lits.get(s, 0) | (1 << i)
        self.has_dstar = self.star2 != 0
        self.nlit = len(segs) - bin(self.star1).count("1") - bin(self.star2).count("1")
        self.accept = 1 << self.m

    def _closure(self, S):
        star2 = self.star2
        while True:
            T = S | ((S & star2) << 1)
            if T == S:
                return S
            S = T

    def match(self, psegs):
        n = len(psegs)
        if not self.has_dstar:
            if n != self.m:
                return False
        elif n < self.m - bin(self.star2).count("1"):
            return False
        star2 = self.star2
        any_mask = self.star1 | star2
        lits = self.lits
        S = self._closure(1)
        for seg in psegs:
            mm = any_mask | lits.get(seg, 0)
            S = (((S & mm & ~star2) << 1) | (S & star2))
            if not S:
                return False
            S = self._closure(S)
        return bool(S & self.accept)


def evaluate_access(rules, requests) -> list[str]:
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    compiled = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")
        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")
        effect, principal, action, resource = fields
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")
        if not _PRINCIPAL.fullmatch(principal):
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        if not _ACTION.fullmatch(action):
            raise ValueError(f"rule {i}: bad action {action!r}")
        if not _RESOURCE.fullmatch(resource):
            raise ValueError(f"rule {i}: bad resource {resource!r}")

        if principal == "*":
            pkind, pname, P = 0, None, 0
        elif principal.startswith("user:"):
            pkind, pname, P = 2, principal[5:], 2
        else:
            pkind, pname, P = 1, principal[6:], 1
        if action == "*":
            actions, A = None, 0
        else:
            actions, A = frozenset(action.split(",")), 1
        rsegs = _segments(resource)
        pat = _Pattern(rsegs)
        spec = (pat.nlit, P, A)
        compiled.append((i, effect == "DENY", pkind, pname, actions, resource, pat, spec))

    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")
        user, groups, action, path = req
        if not _is_name(user):
            raise ValueError(f"request {j}: bad user {user!r}")
        if not isinstance(groups, list) or not all(_is_name(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")
        if not (isinstance(action, str) and _WORD.fullmatch(action)):
            raise ValueError(f"request {j}: bad action {action!r}")
        if not (isinstance(path, str) and _PATH.fullmatch(path)):
            raise ValueError(f"request {j}: bad path {path!r}")

    # Most specific first; within equal specificity, by index.
    order = sorted(compiled, key=lambda r: (tuple(-x for x in r[7]), r[0]))

    results = []
    for user, groups, action, path in requests:
        gset = set(groups)
        psegs = _segments(path)
        memo = {}
        best_spec = None
        deny_idx = None
        allow_idx = None
        for (i, is_deny, pkind, pname, actions, resource, pat, spec) in order:
            if best_spec is not None and spec != best_spec:
                break
            if pkind == 2:
                if pname != user:
                    continue
            elif pkind == 1:
                if pname not in gset:
                    continue
            if actions is not None and action not in actions:
                continue
            m = memo.get(resource)
            if m is None:
                m = pat.match(psegs)
                memo[resource] = m
            if not m:
                continue
            best_spec = spec
            if is_deny:
                if deny_idx is None:
                    deny_idx = i
            elif allow_idx is None:
                allow_idx = i
        if best_spec is None:
            results.append("DENY by default")
        elif deny_idx is not None:
            results.append(f"DENY by rule {deny_idx}")
        else:
            results.append(f"ALLOW by rule {allow_idx}")
    return results

import json
import re

_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _type_name(v):
    # bool must be checked before int, since bool is a subclass of int
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, dict):
        return "dict"
    if isinstance(v, list):
        return "list"
    if isinstance(v, str):
        return "str"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    return type(v).__name__


def _copy(v):
    # Fresh deep copy with no memo: aliased input objects become independent copies
    if isinstance(v, dict):
        return {k: _copy(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_copy(x) for x in v]
    return v


def _child_path(path, name):
    if _IDENT_RE.fullmatch(name):
        return path + "." + name
    return path + "[" + json.dumps(name, ensure_ascii=False) + "]"


def _merge(target, overlay, path, layer_idx, warnings):
    L = layer_idx
    for key, value in overlay.items():
        if not isinstance(key, str):
            raise TypeError(f"layer {L}: non-string key at {path}")

        if key.startswith("-"):
            kind, name = "delete", key[1:]
        elif key.endswith("+"):
            kind, name = "append", key[:-1]
        else:
            kind, name = "set", key

        if name == "":
            raise ValueError(f"layer {L}: empty key name at {path}")

        q = _child_path(path, name)

        if kind == "delete":
            if value is not None:
                raise ValueError(f"layer {L}: delete directive needs null at {q}")
            if name in target:
                del target[name]
            else:
                warnings.append(f"layer {L}: delete of missing key at {q}")

        elif kind == "append":
            if not isinstance(value, list):
                raise ValueError(f"layer {L}: append directive needs a list at {q}")
            if name not in target:
                target[name] = _copy(value)
            elif isinstance(target[name], list):
                target[name].extend(_copy(x) for x in value)
            else:
                raise ValueError(
                    f"layer {L}: cannot append to {_type_name(target[name])} at {q}"
                )

        else:  # set
            if name in target:
                old_t = _type_name(target[name])
                new_t = _type_name(value)
                if old_t != new_t:
                    warnings.append(f"layer {L}: type change at {q}: {old_t} -> {new_t}")
            if isinstance(value, dict):
                if not (name in target and isinstance(target[name], dict)):
                    target[name] = {}
                _merge(target[name], value, q, L, warnings)
            else:
                target[name] = _copy(value)


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")
    result = {}
    warnings = []
    for idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {idx} is not a dict")
        _merge(result, layer, "$", idx, warnings)
    return result, warnings

import re
import datetime

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_KINDS = ("credit", "debit", "fee")


def _to_cents(s):
    """Convert a validated, unsigned decimal string to integer cents."""
    if "." in s:
        whole, frac = s.split(".")
    else:
        whole, frac = s, ""
    frac = (frac + "00")[:2]
    return int(whole) * 100 + int(frac)


def _money(cents):
    sign = "-" if cents < 0 else ""
    a = abs(cents)
    return f"{sign}{a // 100:,}.{a % 100:02d}"


def _valid_date(d):
    if not isinstance(d, str) or _DATE_RE.fullmatch(d) is None:
        return False
    y, m, dd = int(d[0:4]), int(d[5:7]), int(d[8:10])
    if not (1900 <= y <= 2999):
        return False
    try:
        datetime.date(y, m, dd)
    except ValueError:
        return False
    return True


def render_statement(opening, entries) -> list[str]:
    # ---- validation ----
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")
    if _OPENING_RE.fullmatch(opening) is None:
        raise ValueError("opening: bad amount " + repr(opening))
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    parsed = []
    prev_date = None
    for i, entry in enumerate(entries):
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")
        date, kind, amount, memo = entry
        if not _valid_date(date):
            raise ValueError(f"entry {i}: bad date {date!r}")
        if prev_date is not None and date < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        if not isinstance(kind, str) or kind not in _KINDS:
            raise ValueError(f"entry {i}: bad kind {kind!r}")
        if (not isinstance(amount, str)
                or _AMOUNT_RE.fullmatch(amount) is None
                or _to_cents(amount) == 0):
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        if (not isinstance(memo, str)
                or not memo.split()
                or any(ord(ch) < 32 or ord(ch) == 127 for ch in memo)):
            raise ValueError(f"entry {i}: bad memo")
        parsed.append((date, kind, _to_cents(amount), memo))
        prev_date = date

    # ---- processing ----
    if opening.startswith("-"):
        balance = -_to_cents(opening[1:])
    else:
        balance = _to_cents(opening)

    lines = ["Opening balance: " + _money(balance)]
    counts = {"credit": 0, "debit": 0, "fee": 0}
    fee_dates = set()

    def emit(date, kind, cents, memo):
        nonlocal balance
        if kind == "credit":
            balance += cents
            sign = "+"
        else:
            balance -= cents
            sign = "-"
        counts[kind] += 1
        m = " ".join(memo.split())
        if len(m) > 20:
            m = m[:19] + "~"
        m = m.ljust(20)
        amt = (sign + _money(cents)).rjust(14)
        bal = _money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""
        lines.append(f"{date}  {m}  {amt}  {bal}{flag}")

    for date, kind, cents, memo in parsed:
        emit(date, kind, cents, memo)
        if kind == "debit" and balance < 0 and date not in fee_dates:
            fee_dates.add(date)
            emit(date, "fee", 2500, "OVERDRAFT FEE")

    lines.append("Closing balance: " + _money(balance))
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )
    return lines

import re

_NUM = r"(0|[1-9][0-9]*)"
_VERSION_RE = re.compile(_NUM + r"\." + _NUM + r"\." + _NUM + r"(?:~rc([1-9][0-9]*))?")
_MAJOR_RE = re.compile(_NUM + r"\.\*")
_MINOR_RE = re.compile(_NUM + r"\." + _NUM + r"\.\*")
_AT_RE = re.compile(r"@" + _NUM + r"\." + _NUM)


def _parse_version(s):
    """Return a sort key for a valid version string, or None if invalid."""
    m = _VERSION_RE.fullmatch(s)
    if m is None:
        return None
    x, y, z = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if m.group(4) is None:
        return (x, y, z, 1, 0)      # plain release sorts above every rc
    return (x, y, z, 0, int(m.group(4)))


def _is_rc(key):
    return key[3] == 0


def _parse_clause(clause):
    """Return a predicate on version keys, or None if the clause is invalid."""
    if clause == "*":
        return lambda k: True

    m = _MAJOR_RE.fullmatch(clause)
    if m:
        x = int(m.group(1))
        return lambda k: k[0] == x

    m = _MINOR_RE.fullmatch(clause)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k: k[0] == x and k[1] == y

    m = _AT_RE.fullmatch(clause)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda k: k[0] == x and k[1] >= y

    # Two-character operators must be checked before one-character ones.
    ops = [
        ("!=", lambda a, b: a != b),
        (">=", lambda a, b: a >= b),
        ("<=", lambda a, b: a <= b),
        (">", lambda a, b: a > b),
        ("<", lambda a, b: a < b),
        ("=", lambda a, b: a == b),
    ]
    for op, fn in ops:
        if clause.startswith(op):
            v = _parse_version(clause[len(op):])
            if v is None:
                return None
            return lambda k, fn=fn, v=v: fn(k, v)

    v = _parse_version(clause)
    if v is not None:
        return lambda k: k == v
    return None


def pick_version(available, constraint):
    # 1-2: validate available
    if not isinstance(available, list):
        raise TypeError("available must be a list")
    keys = []
    for i, element in enumerate(available):
        key = _parse_version(element) if isinstance(element, str) else None
        if key is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        keys.append(key)

    # 3-4: validate constraint type / emptiness
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # 5: parse alternatives and clauses
    alternatives = []
    for a, alt in enumerate(constraint.split("|"), start=1):
        alt = alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")
        if alt == "":
            raise ValueError(f"alternative {a} is empty")
        preds = []
        for c, clause in enumerate(alt.split(","), start=1):
            clause = clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(
                    f"alternative {a}, clause {c}: invalid clause {clause!r}"
                )
            preds.append(pred)
        alternatives.append((allow_rc, preds))

    # Matching
    best_key = None
    best = None
    for s, key in zip(available, keys):
        rc = _is_rc(key)
        ok = any(
            (not rc or allow_rc) and all(p(key) for p in preds)
            for allow_rc, preds in alternatives
        )
        if ok and (best_key is None or key > best_key):
            best_key, best = key, s
    return best

import re

_KEY_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_-]*')
_INT_RE = re.compile(r'-?(0|[1-9][0-9]*)')
_ESCAPES = {'\\': '\\', '"': '"', 'n': '\n', 't': '\t'}

_MAP = 0
_LIST = 1


def _convert_scalar(text):
    """Return (True, value) on success or (False, message) on error."""
    if text.startswith('"'):
        n = len(text)
        buf = []
        i = 1
        while i < n:
            c = text[i]
            if c == '\\':
                if i + 1 >= n:
                    return (False, "bad escape")
                nxt = text[i + 1]
                if nxt not in _ESCAPES:
                    return (False, "bad escape")
                buf.append(_ESCAPES[nxt])
                i += 2
            elif c == '"':
                if i != n - 1:
                    return (False, "bad string")
                return (True, ''.join(buf))
            else:
                buf.append(c)
                i += 1
        return (False, "bad string")
    if text == "true":
        return (True, True)
    if text == "false":
        return (True, False)
    if text == "null":
        return (True, None)
    if _INT_RE.fullmatch(text):
        return (True, int(text))
    return (True, text)


def parse_outline(text: str) -> tuple:
    try:
        return _parse(text)
    except Exception as e:  # safety net: never raise
        return ("error", 0, "internal error: %s" % e)


def _parse(text):
    lines = text.split("\n")
    root = None
    stack = []        # list of [indent, kind, container]
    pending = None    # (indent, container, slot) of the last opener, or None

    for lineno, line in enumerate(lines, 1):
        # Find LEAD
        j = 0
        n = len(line)
        while j < n and line[j] in " \t":
            j += 1
        if j == n:
            continue  # blank
        lead = line[:j]
        rest = line[j:]
        if rest.startswith('#'):
            continue  # comment

        indent = j
        # 1. tab in indentation
        if '\t' in lead:
            return ("error", lineno, "tab in indentation")

        # 2/3. entry syntax
        key = None
        if rest == "-" or rest.startswith("- "):
            kind = _LIST
            t = rest[2:].strip(' ')
        else:
            kind = _MAP
            idx = rest.find(':')
            if idx < 0:
                return ("error", lineno, "invalid entry")
            key = rest[:idx]
            if not _KEY_RE.fullmatch(key):
                return ("error", lineno, "invalid entry")
            after = rest[idx + 1:]
            if after.strip(' ') == "":
                t = ""
            elif after[0] != ' ':
                return ("error", lineno, "invalid entry")
            else:
                t = after.strip(' ')

        is_opener = (t == "")
        # 4. scalar conversion
        if is_opener:
            value = None
        else:
            ok, res = _convert_scalar(t)
            if not ok:
                return ("error", lineno, res)
            value = res

        # Structure
        if not stack:
            if indent != 0:
                return ("error", lineno, "unexpected indent")
            container = {} if kind == _MAP else []
            root = container
            stack.append([0, kind, container])
        elif pending is not None and indent > pending[0]:
            container = {} if kind == _MAP else []
            pcont, pslot = pending[1], pending[2]
            pcont[pslot] = container
            stack.append([indent, kind, container])
        else:
            top = stack[-1]
            if indent > top[0]:
                return ("error", lineno, "unexpected indent")
            if indent < top[0]:
                while stack[-1][0] > indent:
                    stack.pop()
                if stack[-1][0] != indent:
                    return ("error", lineno, "inconsistent dedent")
            top = stack[-1]
            if top[1] != kind:
                return ("error", lineno, "mixed block")
            container = top[2]
            if kind == _MAP and key in container:
                return ("error", lineno, "duplicate key '%s'" % key)

        # Add the entry
        if kind == _MAP:
            container[key] = value
            pending = (indent, container, key) if is_opener else None
        else:
            container.append(value)
            pending = (indent, container, len(container) - 1) if is_opener else None

    return ("ok", root)

import sys
import operator

_DIGITS = set("0123456789")
_LETTERS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
_WORDCH = _LETTERS | _DIGITS | {"."}
_KEYWORDS = {"and", "or", "not", "in", "has"}
_CMP = {"=": operator.eq, "!=": operator.ne, "<": operator.lt,
        "<=": operator.le, ">": operator.gt, ">=": operator.ge}


class _SieveError(Exception):
    def __init__(self, pos, msg):
        self.pos = pos
        self.msg = msg


def _to_int(s):
    try:
        return int(s)
    except ValueError:
        # Python 3.11+ refuses very long digit strings unless the limit is lifted.
        getter = getattr(sys, "get_int_max_str_digits", None)
        setter = getattr(sys, "set_int_max_str_digits", None)
        if getter is None or setter is None:
            raise
        old = getter()
        try:
            setter(0)
            return int(s)
        finally:
            setter(old)


def _lex(q):
    n = len(q)
    i = 0
    toks = []
    while i < n:
        c = q[i]
        if c in " \t\n":
            i += 1
            continue
        if c in "()[],":
            toks.append((c, c, i, i + 1))
            i += 1
            continue
        if c in "!<>=":
            if c != "=" and i + 1 < n and q[i + 1] == "=":
                toks.append(("OP", c + "=", i, i + 2))
                i += 2
                continue
            if c == "!":
                raise _SieveError(i, "unexpected character '!'")
            toks.append(("OP", c, i, i + 1))
            i += 1
            continue
        if c in _DIGITS or (c == "-" and i + 1 < n and q[i + 1] in _DIGITS):
            j = i + 1
            while j < n and q[j] in _DIGITS:
                j += 1
            toks.append(("INT", _to_int(q[i:j]), i, j))
            i = j
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise _SieveError(i, "unterminated string")
                ch = q[j]
                if ch == "\\":
                    if j + 1 < n and q[j + 1] in '"\\':
                        buf.append(q[j + 1])
                        j += 2
                    else:
                        raise _SieveError(j, "bad escape")
                elif ch == '"':
                    j += 1
                    break
                else:
                    buf.append(ch)
                    j += 1
            toks.append(("STR", "".join(buf), i, j))
            i = j
            continue
        if c in _LETTERS:
            j = i + 1
            while j < n and q[j] in _WORDCH:
                j += 1
            w = q[i:j]
            toks.append(("KW" if w in _KEYWORDS else "FIELD", w, i, j))
            i = j
            continue
        raise _SieveError(i, "unexpected character '%s'" % c)
    toks.append(("END", None, n, n))
    return toks


def _parse(q, toks):
    """Iterative parser producing RPN. Errors match recursive descent."""
    def err(t):
        if t[0] == "END":
            raise _SieveError(t[2], "unexpected end of input")
        raise _SieveError(t[2], "unexpected token '%s'" % q[t[2]:t[3]])

    def is_kw(t, w):
        return t[0] == "KW" and t[1] == w

    rpn = []
    ops = []  # 'not', 'and', 'or', '('
    p = 0
    expect_operand = True
    while True:
        t = toks[p]
        if expect_operand:
            if is_kw(t, "not"):
                ops.append("not")
                p += 1
                continue
            if t[0] == "(":
                ops.append("(")
                p += 1
                continue
            if is_kw(t, "has"):
                f = toks[p + 1]
                if f[0] != "FIELD":
                    err(f)
                rpn.append(("has", f[1]))
                p += 2
            elif t[0] == "FIELD":
                nt = toks[p + 1]
                if nt[0] == "OP":
                    lit = toks[p + 2]
                    if lit[0] not in ("INT", "STR"):
                        err(lit)
                    rpn.append(("cmp", t[1], nt[1], lit[1]))
                    p += 3
                elif is_kw(nt, "in"):
                    b = toks[p + 2]
                    if b[0] != "[":
                        err(b)
                    p += 3
                    lits = []
                    while True:
                        lit = toks[p]
                        if lit[0] not in ("INT", "STR"):
                            err(lit)
                        lits.append(lit[1])
                        p += 1
                        s = toks[p]
                        if s[0] == ",":
                            p += 1
                            continue
                        if s[0] == "]":
                            p += 1
                            break
                        err(s)
                    rpn.append(("in", t[1], lits))
                else:
                    err(nt)
            else:
                err(t)
            # completed a primary: apply pending nots
            while ops and ops[-1] == "not":
                ops.pop()
                rpn.append(("not",))
            expect_operand = False
        else:
            if is_kw(t, "and"):
                while ops and ops[-1] == "and":
                    rpn.append((ops.pop(),))
                ops.append("and")
                expect_operand = True
                p += 1
            elif is_kw(t, "or"):
                while ops and ops[-1] in ("and", "or"):
                    rpn.append((ops.pop(),))
                ops.append("or")
                expect_operand = True
                p += 1
            elif t[0] == ")":
                while ops and ops[-1] in ("and", "or"):
                    rpn.append((ops.pop(),))
                if not ops or ops[-1] != "(":
                    err(t)
                ops.pop()
                while ops and ops[-1] == "not":
                    ops.pop()
                    rpn.append(("not",))
                p += 1
            elif t[0] == "END":
                while ops and ops[-1] in ("and", "or"):
                    rpn.append((ops.pop(),))
                if ops:
                    err(t)
                return rpn
            else:
                err(t)


def _evaluate(rpn, records):
    # TRUE=2, UNKNOWN=1, FALSE=0
    stack = []
    for node in rpn:
        kind = node[0]
        if kind == "cmp":
            _, field, op, lit = node
            f = _CMP[op]
            lt = type(lit)
            mismatch = 0 if op == "=" else (2 if op == "!=" else 1)
            res = []
            app = res.append
            for r in records:
                if field not in r:
                    app(1)
                    continue
                v = r[field]
                if type(v) is not lt:
                    app(mismatch)
                else:
                    app(2 if f(v, lit) else 0)
            stack.append(res)
        elif kind == "in":
            _, field, lits = node
            ints = set(x for x in lits if type(x) is int)
            strs = set(x for x in lits if type(x) is str)
            res = []
            app = res.append
            for r in records:
                if field not in r:
                    app(1)
                    continue
                v = r[field]
                if type(v) is int:
                    app(2 if v in ints else 0)
                else:
                    app(2 if v in strs else 0)
            stack.append(res)
        elif kind == "has":
            field = node[1]
            stack.append([2 if field in r else 0 for r in records])
        elif kind == "not":
            a = stack.pop()
            stack.append([2 - x for x in a])
        elif kind == "and":
            b = stack.pop()
            a = stack.pop()
            stack.append(list(map(min, a, b)))
        else:  # or
            b = stack.pop()
            a = stack.pop()
            stack.append(list(map(max, a, b)))
    final = stack[-1]
    return [i for i, x in enumerate(final) if x == 2]


def filter_records(query: str, records: list) -> tuple:
    try:
        toks = _lex(query)
        rpn = _parse(query, toks)
        if not records:
            return ("ok", [])
        return ("ok", _evaluate(rpn, records))
    except _SieveError as e:
        return ("error", e.pos, e.msg)
    except Exception as e:  # never raise
        return ("error", 0, "internal error: %s" % e)

import re

_TOK_RE = re.compile(r' +|[0-9]+|[a-z_][a-z0-9_]*|<=|>=|==|!=|[-+*/%^()?:<>]|.', re.DOTALL)

_ARITH_PREC = {'+': 2, '-': 2, '*': 3, '/': 3, '%': 3, '^': 5}
_CMP_OPS = {'<', '<=', '>', '>=', '==', '!='}
_OPCHARS = set('+-*/%^()?:<>')
_NEG_PREC = 4


class _SyntaxErr(Exception):
    pass


def _tokenize(src):
    toks = []
    for m in _TOK_RE.finditer(src):
        t = m.group()
        if t[0] == ' ':
            continue
        c = t[0]
        if '0' <= c <= '9':
            kind = 'int'
        elif c == '_' or 'a' <= c <= 'z':
            kind = 'name'
        elif t in ('<=', '>=', '==', '!=') or (len(t) == 1 and c in _OPCHARS):
            kind = 'op'
        else:
            kind = 'bad'
        toks.append((kind, t, m.start()))
    toks.append(('end', '', len(src)))
    return toks


def _err_for(tok):
    kind, text, pos = tok
    if kind == 'end':
        return ("error", pos, "unexpected end of input")
    if kind == 'bad':
        return ("error", pos, "unexpected character '%s'" % text)
    return ("error", pos, "unexpected token '%s'" % text)


def _apply(ops, vals):
    prec, op, pos = ops.pop()
    if op == 'neg':
        x = vals.pop()
        vals.append(('u', x))
    else:
        r = vals.pop()
        l = vals.pop()
        vals.append(('b', op, pos, l, r))


def _reduce(frame):
    ops, vals = frame[1], frame[2]
    while ops:
        _apply(ops, vals)
    return vals[0]


def _parse(toks):
    # frame: [type, ops, vals, cmp_used, then_node]
    frames = [['top', [], [], False, None]]
    expect_operand = True

    def close_else():
        while frames[-1][0] == 'else':
            e = frames.pop()
            b = _reduce(e)
            f = frames[-1]
            f[2] = [('t', f[2][0], e[4], b)]
            f[1] = []

    for tok in toks:
        kind, text, pos = tok
        top = frames[-1]
        if expect_operand:
            if kind == 'int':
                top[2].append(('n', int(text)))
                expect_operand = False
            elif kind == 'name':
                top[2].append(('v', text, pos))
                expect_operand = False
            elif kind == 'op' and text == '(':
                frames.append(['paren', [], [], False, None])
            elif kind == 'op' and text == '-':
                top[1].append((_NEG_PREC, 'neg', pos))
            else:
                return _err_for(tok)
        else:
            if kind == 'op' and (text in _ARITH_PREC or text in _CMP_OPS):
                if text in _CMP_OPS:
                    if top[3]:
                        return _err_for(tok)
                    top[3] = True
                    p = 1
                else:
                    p = _ARITH_PREC[text]
                ops, vals = top[1], top[2]
                while ops and (ops[-1][0] > p or (ops[-1][0] == p and p != 5)):
                    _apply(ops, vals)
                ops.append((p, text, pos))
                expect_operand = True
            elif kind == 'op' and text == '?':
                c = _reduce(top)
                top[2] = [c]
                top[1] = []
                frames.append(['then', [], [], False, None])
                expect_operand = True
            elif kind == 'op' and text == ':':
                close_else()
                if frames[-1][0] != 'then':
                    return _err_for(tok)
                t = frames.pop()
                a = _reduce(t)
                frames.append(['else', [], [], False, a])
                expect_operand = True
            elif kind == 'op' and text == ')':
                close_else()
                if frames[-1][0] != 'paren':
                    return _err_for(tok)
                p = frames.pop()
                x = _reduce(p)
                frames[-1][2].append(x)
            elif kind == 'end':
                close_else()
                if frames[-1][0] != 'top':
                    return _err_for(tok)
                return ('ok', _reduce(frames[-1]))
            else:
                return _err_for(tok)
    return _err_for(toks[-1])  # unreachable in practice


def _eval(root, env):
    vals = []
    st = [(root, 0)]
    while st:
        node, s = st.pop()
        k = node[0]
        if k == 'n':
            vals.append(node[1])
        elif k == 'v':
            name = node[1]
            if name not in env:
                return ("error", node[2], "unknown name '%s'" % name)
            vals.append(env[name])
        elif k == 'u':
            if s == 0:
                st.append((node, 1))
                st.append((node[1], 0))
            else:
                vals[-1] = -vals[-1]
        elif k == 'b':
            if s == 0:
                st.append((node, 1))
                st.append((node[4], 0))
                st.append((node[3], 0))
            else:
                b = vals.pop()
                a = vals.pop()
                op = node[1]
                pos = node[2]
                if op == '+':
                    r = a + b
                elif op == '-':
                    r = a - b
                elif op == '*':
                    r = a * b
                elif op == '/':
                    if b == 0:
                        return ("error", pos, "division by zero")
                    r = a // b
                elif op == '%':
                    if b == 0:
                        return ("error", pos, "division by zero")
                    r = a % b
                elif op == '^':
                    if b < 0:
                        return ("error", pos, "negative exponent")
                    if b > 256:
                        return ("error", pos, "exponent too large")
                    r = a ** b
                elif op == '<':
                    r = 1 if a < b else 0
                elif op == '<=':
                    r = 1 if a <= b else 0
                elif op == '>':
                    r = 1 if a > b else 0
                elif op == '>=':
                    r = 1 if a >= b else 0
                elif op == '==':
                    r = 1 if a == b else 0
                else:  # '!='
                    r = 1 if a != b else 0
                vals.append(r)
        else:  # ternary
            if s == 0:
                st.append((node, 1))
                st.append((node[1], 0))
            else:
                c = vals.pop()
                st.append((node[2] if c != 0 else node[3], 0))
    return ("ok", vals[0])


def evaluate(src: str, env: dict) -> tuple:
    try:
        toks = _tokenize(src)
        res = _parse(toks)
        if res[0] == 'error':
            return res
        return _eval(res[1], env)
    except Exception as e:  # should not happen; never raise
        return ("error", 0, "internal error: %s" % e)

def fence_report(colors: list[int], operations: list[tuple]) -> list[tuple[int, int]]:
    n = len(colors)
    if n == 0 or not operations:
        return []

    E = (0, None, None, 0, 0, 0, 0)  # len, lc, rc, runs, pre, suf, mx

    def merge(a, b):
        a0 = a[0]
        if a0 == 0:
            return b
        b0 = b[0]
        if b0 == 0:
            return a
        if a[2] == b[1]:
            a4 = a[4]; b4 = b[4]; a5 = a[5]; b5 = b[5]
            pre = a4 + b4 if a4 == a0 else a4
            suf = b5 + a5 if b5 == b0 else b5
            mx = a[6]
            if b[6] > mx:
                mx = b[6]
            j = a5 + b4
            if j > mx:
                mx = j
            return (a0 + b0, a[1], b[2], a[3] + b[3] - 1, pre, suf, mx)
        else:
            mx = a[6] if a[6] > b[6] else b[6]
            return (a0 + b0, a[1], b[2], a[3] + b[3], a[4], b[5], mx)

    log = 0
    while (1 << log) < n:
        log += 1
    size = 1 << log
    d = [E] * (2 * size)
    lz = [None] * size
    for i, c in enumerate(colors):
        d[size + i] = (1, c, c, 1, 1, 1, 1)
    for k in range(size - 1, 0, -1):
        d[k] = merge(d[2 * k], d[2 * k + 1])

    def all_apply(k, c):
        L = d[k][0]
        if L:
            d[k] = (L, c, c, 1, L, L, L)
        if k < size:
            lz[k] = c

    def push(k):
        c = lz[k]
        if c is not None:
            all_apply(2 * k, c)
            all_apply(2 * k + 1, c)
            lz[k] = None

    out = []
    for op in operations:
        if op[0] == "paint":
            _, l, r, c = op
            l += size
            r += size + 1
            for i in range(log, 0, -1):
                if ((l >> i) << i) != l:
                    push(l >> i)
                if ((r >> i) << i) != r:
                    push((r - 1) >> i)
            l2, r2 = l, r
            while l2 < r2:
                if l2 & 1:
                    all_apply(l2, c)
                    l2 += 1
                if r2 & 1:
                    r2 -= 1
                    all_apply(r2, c)
                l2 >>= 1
                r2 >>= 1
            for i in range(1, log + 1):
                if ((l >> i) << i) != l:
                    k = l >> i
                    d[k] = merge(d[2 * k], d[2 * k + 1])
                if ((r >> i) << i) != r:
                    k = (r - 1) >> i
                    d[k] = merge(d[2 * k], d[2 * k + 1])
        else:
            _, l, r = op
            l += size
            r += size + 1
            for i in range(log, 0, -1):
                if ((l >> i) << i) != l:
                    push(l >> i)
                if ((r >> i) << i) != r:
                    push((r - 1) >> i)
            sml = E
            smr = E
            while l < r:
                if l & 1:
                    sml = merge(sml, d[l])
                    l += 1
                if r & 1:
                    r -= 1
                    smr = merge(d[r], smr)
                l >>= 1
                r >>= 1
            res = merge(sml, smr)
            out.append((res[3], res[6]))
    return out

def leaderboard_ranks(submissions: list[tuple[str, int]]) -> list[int]:
    n = len(submissions)
    if n == 0:
        return []

    # Pass 1: find submissions that create a new (BEST, BEST TIME) key.
    best = {}
    is_key = [False] * n
    keys = []
    for i, (p, s) in enumerate(submissions):
        b = best.get(p)
        if b is None or s > b:
            best[p] = s
            is_key[i] = True
            keys.append((-s, i))

    # Sort keys by leaderboard order (score desc, index asc) and assign slots.
    keys.sort()
    m = len(keys)
    pos_of = {}  # submission index -> 1-based Fenwick slot
    for k, (_, i) in enumerate(keys, 1):
        pos_of[i] = k

    tree = [0] * (m + 1)

    def update(i, d):
        while i <= m:
            tree[i] += d
            i += i & (-i)

    def query(i):
        r = 0
        while i > 0:
            r += tree[i]
            i -= i & (-i)
        return r

    # Pass 2: replay submissions, keeping exactly one live key per player.
    cur_pos = {}  # player -> current Fenwick slot
    res = [0] * n
    for i, (p, s) in enumerate(submissions):
        if is_key[i]:
            old = cur_pos.get(p)
            if old is not None:
                update(old, -1)
            np_ = pos_of[i]
            update(np_, 1)
            cur_pos[p] = np_
        else:
            np_ = cur_pos[p]
        res[i] = query(np_ - 1) + 1
    return res

_DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _int_to_base(n: int, base: int) -> str:
    """Convert a non-negative int of moderate size to a string in `base`."""
    if n == 0:
        return "0"
    out = []
    while n:
        n, m = divmod(n, base)
        out.append(_DIGITS[m])
    return "".join(reversed(out))


def format_base(p: int, q: int, base: int, k: int) -> str:
    if q == 0:
        raise ValueError("q must be nonzero")
    if not (2 <= base <= 36):
        raise ValueError("base must be in 2..36")
    if k < 0:
        raise ValueError("k must be non-negative")

    negative = (p < 0) != (q < 0) and p != 0
    a, q = abs(p), abs(q)

    # Integer part and remainder.
    I, r = divmod(a, q)

    # Generate k fractional digits (truncated) by chunked long division.
    # Chunk size C: about 60 bits worth of digits per chunk.
    C = max(1, 60 // base.bit_length())
    powC = base ** C
    frac = []
    append = frac.append
    remaining = k
    while remaining:
        c = C if remaining >= C else remaining
        mult = powC if c == C else base ** c
        r *= mult
        d, r = divmod(r, q)
        # Extract exactly c digits of d (most significant first).
        if base == 10:
            s = str(d).zfill(c)
            frac.extend(ord(ch) - 48 for ch in s)
        else:
            tmp = [0] * c
            for i in range(c - 1, -1, -1):
                d, m = divmod(d, base)
                tmp[i] = m
            frac.extend(tmp)
        remaining -= c

    # Rounding: remainder r / q is the leftover fraction of N.
    twice = 2 * r
    if twice > q:
        round_up = True
    elif twice < q:
        round_up = False
    else:
        # Tie: round to even N. Determine parity of truncated N.
        if base % 2 == 0:
            parity = (frac[-1] & 1) if k > 0 else (I & 1)
        else:
            # base^j is odd for all j, so N ≡ I + sum of digits (mod 2)
            parity = (I + sum(frac)) & 1
        round_up = parity == 1

    if round_up:
        i = k - 1
        bm1 = base - 1
        while i >= 0 and frac[i] == bm1:
            frac[i] = 0
            i -= 1
        if i >= 0:
            frac[i] += 1
        else:
            I += 1

    # Strip trailing zeros of the fractional part.
    end = len(frac)
    while end > 0 and frac[end - 1] == 0:
        end -= 1

    if I == 0 and end == 0:
        return "0"

    result = _int_to_base(I, base)
    if end > 0:
        if base == 10:
            result += "." + "".join(map(str, frac[:end]))
        else:
            D = _DIGITS
            result += "." + "".join([D[x] for x in frac[:end]])
    return ("-" + result) if negative else result

import re
from fractions import Fraction

_LITERAL = re.compile(r'([+-]?)([0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE]([+-]?[0-9]+))?')


def _parse(x):
    if not isinstance(x, str):
        raise ValueError("literal must be a string")
    m = _LITERAL.fullmatch(x)
    if m is None:
        raise ValueError("invalid decimal literal: %r" % (x,))
    sign, mant, exp = m.group(1), m.group(2), m.group(3)
    if '.' in mant:
        ip, fp = mant.split('.', 1)
    else:
        ip, fp = mant, ''
    digits = (ip + fp) or '0'
    val = Fraction(int(digits), 10 ** len(fp))
    if exp is not None:
        e = int(exp)
        if e >= 0:
            val *= 10 ** e
        else:
            val /= 10 ** (-e)
    if sign == '-':
        val = -val
    return val


def _fmt(p, q, negative):
    if p == 0:
        return "0/1"
    return ("-" if negative else "") + "%d/%d" % (p, q)


def closest_fraction(x: str, max_num: int, max_den: int) -> str:
    val = _parse(x)
    if max_num < 0 or max_den < 1:
        raise ValueError("invalid bounds")
    N, D = max_num, max_den
    neg = val < 0
    if neg:
        val = -val
    if val == 0 or N == 0:
        return "0/1"
    if val >= N:
        return _fmt(N, 1, neg)

    P, Q = val.numerator, val.denominator
    # Stern-Brocot descent with batched steps, restricted to p<=N, q<=D.
    pl, ql, pr, qr = 0, 1, 1, 0
    while True:
        moved = False
        num = P * ql - Q * pl          # Q*(x - left)*ql >= 0
        if num == 0:
            return _fmt(pl, ql, neg)
        den = Q * pr - P * qr          # >= 0
        if den == 0:
            return _fmt(pr, qr, neg)
        # move left toward x
        t = num // den
        if pr:
            t = min(t, (N - pl) // pr)
        if qr:
            t = min(t, (D - ql) // qr)
        if t > 0:
            pl += t * pr
            ql += t * qr
            moved = True
        num = P * ql - Q * pl
        if num == 0:
            return _fmt(pl, ql, neg)
        den = Q * pr - P * qr
        if den == 0:
            return _fmt(pr, qr, neg)
        # move right toward x
        t = den // num
        if pl:
            t = min(t, (N - pr) // pl)
        t = min(t, (D - qr) // ql)
        if t > 0:
            pr += t * pl
            qr += t * ql
            moved = True
        if Q * pr == P * qr:
            return _fmt(pr, qr, neg)
        if not moved:
            break

    L = Fraction(pl, ql)
    U = Fraction(pr, qr)
    dl = val - L
    du = U - val
    if dl < du:
        return _fmt(pl, ql, neg)
    if du < dl:
        return _fmt(pr, qr, neg)
    # tie: smaller denominator, then closer to zero (L, since both >= 0)
    if ql < qr:
        return _fmt(pl, ql, neg)
    if qr < ql:
        return _fmt(pr, qr, neg)
    return _fmt(pl, ql, neg)

from bisect import bisect_left, bisect_right

def run_ops(ops: list[tuple]) -> list:
    # Offline coordinate compression of all keys that may ever be stored/deleted.
    keyset = set()
    for op in ops:
        if op[0] == "set" or op[0] == "del":
            keyset.add(op[2])
    keys = sorted(keyset)
    N = len(keys)
    kidx = {k: i for i, k in enumerate(keys)}

    # Node storage; node 0 is the shared empty node.
    L = [0]; R = [0]; C = [0]; S = [0]
    roots = [0]
    out = []
    append = out.append

    def update(root, pos, c, s):
        path = []
        node = root
        lo, hi = 0, N - 1
        while lo < hi:
            mid = (lo + hi) >> 1
            if pos <= mid:
                path.append((node, 0))
                node = L[node]
                hi = mid
            else:
                path.append((node, 1))
                node = R[node]
                lo = mid + 1
        cur = len(C)
        L.append(0); R.append(0); C.append(c); S.append(s)
        for nd, d in reversed(path):
            if d == 0:
                l, r = cur, R[nd]
            else:
                l, r = L[nd], cur
            cur = len(C)
            L.append(l); R.append(r)
            C.append(C[l] + C[r]); S.append(S[l] + S[r])
        return cur

    def leaf(root, pos):
        node = root
        lo, hi = 0, N - 1
        while lo < hi:
            mid = (lo + hi) >> 1
            if pos <= mid:
                node = L[node]; hi = mid
            else:
                node = R[node]; lo = mid + 1
        return node

    def prefix(root, i):
        if i < 0:
            return 0, 0
        node = root
        lo, hi = 0, N - 1
        c = s = 0
        while lo < hi:
            mid = (lo + hi) >> 1
            if i <= mid:
                node = L[node]; hi = mid
            else:
                ln = L[node]
                c += C[ln]; s += S[ln]
                node = R[node]; lo = mid + 1
        return c + C[node], s + S[node]

    for op in ops:
        name = op[0]
        v = op[1]
        if not isinstance(v, int) or v < 0 or v >= len(roots):
            append("BADVER")
            continue
        root = roots[v]
        if name == "set":
            pos = kidx[op[2]]
            roots.append(update(root, pos, 1, op[3]))
            append(len(roots) - 1)
        elif name == "del":
            pos = kidx[op[2]]
            if C[leaf(root, pos)] == 0:
                append("NOKEY")
            else:
                roots.append(update(root, pos, 0, 0))
                append(len(roots) - 1)
        elif name == "get":
            pos = kidx.get(op[2])
            if pos is None:
                append(None)
            else:
                nd = leaf(root, pos)
                append(S[nd] if C[nd] else None)
        elif name == "count" or name == "sum":
            lo, hi = op[2], op[3]
            if lo > hi or N == 0:
                append(0)
                continue
            a = bisect_left(keys, lo)
            b = bisect_right(keys, hi) - 1
            if a > b:
                append(0)
                continue
            c2, s2 = prefix(root, b)
            c1, s1 = prefix(root, a - 1)
            append(c2 - c1 if name == "count" else s2 - s1)
        else:  # kth
            k = op[2]
            if k < 1 or k > C[root]:
                append(None)
                continue
            node = root
            lo, hi = 0, N - 1
            while lo < hi:
                mid = (lo + hi) >> 1
                ln = L[node]
                if C[ln] >= k:
                    node = ln; hi = mid
                else:
                    k -= C[ln]
                    node = R[node]; lo = mid + 1
            append(keys[lo])
    return out

from bisect import bisect_left, bisect_right, insort

class _SortedKeys:
    LOAD = 256

    def __init__(self):
        self.blocks = []
        self.mins = []

    def floor(self, x):
        """Largest key <= x, or None."""
        i = bisect_right(self.mins, x) - 1
        if i < 0:
            return None
        b = self.blocks[i]
        return b[bisect_right(b, x) - 1]

    def higher(self, x):
        """Smallest key > x, or None."""
        if not self.blocks:
            return None
        i = bisect_right(self.mins, x) - 1
        if i < 0:
            return self.blocks[0][0]
        b = self.blocks[i]
        j = bisect_right(b, x)
        if j < len(b):
            return b[j]
        if i + 1 < len(self.blocks):
            return self.blocks[i + 1][0]
        return None

    def add(self, x):
        if not self.blocks:
            self.blocks.append([x])
            self.mins.append(x)
            return
        i = bisect_right(self.mins, x) - 1
        if i < 0:
            i = 0
        b = self.blocks[i]
        insort(b, x)
        self.mins[i] = b[0]
        if len(b) > 2 * self.LOAD:
            nb = b[self.LOAD:]
            del b[self.LOAD:]
            self.blocks.insert(i + 1, nb)
            self.mins.insert(i + 1, nb[0])

    def remove(self, x):
        i = bisect_right(self.mins, x) - 1
        b = self.blocks[i]
        j = bisect_left(b, x)
        del b[j]
        if b:
            self.mins[i] = b[0]
        else:
            del self.blocks[i]
            del self.mins[i]


def run_ops(ops):
    keys = _SortedKeys()
    ends = {}     # start -> end (exclusive)
    labs = {}     # start -> label
    total = {}    # label -> painted count
    count = 0     # number of runs
    out = []

    def add_iv(s, e, lab):
        nonlocal count
        keys.add(s)
        ends[s] = e
        labs[s] = lab
        total[lab] = total.get(lab, 0) + (e - s)
        count += 1

    def remove_iv(s):
        nonlocal count
        keys.remove(s)
        e = ends.pop(s)
        lab = labs.pop(s)
        total[lab] -= e - s
        count -= 1
        return e, lab

    def collect(l, r):
        res = []
        s = keys.floor(l)
        if s is not None and ends[s] > l:
            res.append(s)
        k = keys.higher(l)
        while k is not None and k < r:
            res.append(k)
            k = keys.higher(k)
        return res

    for op in ops:
        name = op[0]
        if name == "paint":
            _, l, r, label = op
            if l >= r:
                out.append(0)
                continue
            same = 0
            left_piece = right_piece = None
            for s in collect(l, r):
                e, lab = remove_iv(s)
                ov = min(e, r) - max(s, l)
                if lab == label:
                    same += ov
                if s < l:
                    left_piece = (s, l, lab)
                if e > r:
                    right_piece = (r, e, lab)
            ns, ne = l, r
            if left_piece is not None:
                if left_piece[2] == label:
                    ns = left_piece[0]
                else:
                    add_iv(*left_piece)
            if right_piece is not None:
                if right_piece[2] == label:
                    ne = right_piece[1]
                else:
                    add_iv(*right_piece)
            # merge with touching neighbours of same label
            p = keys.floor(ns - 1)
            if p is not None and ends[p] == ns and labs[p] == label:
                remove_iv(p)
                ns = p
            if ne in ends and labs[ne] == label:
                e2, _ = remove_iv(ne)
                ne = e2
            add_iv(ns, ne, label)
            out.append((r - l) - same)

        elif name == "erase":
            _, l, r = op
            if l >= r:
                out.append(0)
                continue
            painted = 0
            pieces = []
            for s in collect(l, r):
                e, lab = remove_iv(s)
                painted += min(e, r) - max(s, l)
                if s < l:
                    pieces.append((s, l, lab))
                if e > r:
                    pieces.append((r, e, lab))
            for pc in pieces:
                add_iv(*pc)
            out.append(painted)

        elif name == "at":
            p = op[1]
            s = keys.floor(p)
            if s is not None and ends[s] > p:
                out.append(labs[s])
            else:
                out.append(None)

        elif name == "runs":
            out.append(count)

        elif name == "total":
            out.append(total.get(op[1], 0))

        elif name == "next_change":
            p = op[1]
            s = keys.floor(p)
            if s is not None and ends[s] > p:
                # runs are maximal, so state at ends[s] differs
                out.append(ends[s])
            else:
                out.append(keys.higher(p))

    return out

from collections import OrderedDict
import heapq


def run_cache(capacity, ops):
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> [value, expires_at or None, seq]; oldest use first
    heap = []              # (expires_at, seq, key) for entries with a ttl
    out = []
    last_t = None
    seq = 0

    def purge(t):
        # Remove every entry whose expiry time is <= t.
        while heap and heap[0][0] <= t:
            _, s, k = heapq.heappop(heap)
            entry = store.get(k)
            if entry is not None and entry[2] == s:
                del store[k]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (not isinstance(ttl, int) or ttl < 1):
                raise ValueError("ttl must be None or a positive int")
            purge(t)
            expires_at = None if ttl is None else t + ttl
            seq += 1
            entry = store.get(key)
            if entry is not None:
                entry[0] = value
                entry[1] = expires_at
                entry[2] = seq
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = [value, expires_at, seq]
            if expires_at is not None:
                heapq.heappush(heap, (expires_at, seq, key))

        elif kind == "get":
            key = op[2]
            purge(t)
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            # Comment runs up to, but not including, the next "\n".
            end = src.find("\n", i)
            new_i = n if end == -1 else end
            col += new_i - i
            i = new_i
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            # FRACTION: "." followed by at least one digit.
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 2
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            # EXPONENT: e/E, optional sign, at least one digit.
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    while k < n and _is_digit(src[k]):
                        k += 1
                    j = k
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
